import { test } from 'node:test';
import assert from 'node:assert/strict';
import { FORMATS, generate } from '../src/index.js';
import { run } from './helpers.js';

const RULES = [
  '/old-blog,/blog',
  '/sale?id=12,/offers/12',
  '/legacy,410',
  '/shop/:cat/*,/store/:cat/items/$2',
  '~^/product/(\\d+)$,/p/$1',
];
const report = run(RULES, { base: 'https://example.com' });

test('Apache output', () => {
  assert.equal(
    generate(report, 'apache').text,
    [
      '# Generated by redirect-map',
      '# Place above other rewrite rules (for WordPress, above "# BEGIN WordPress").',
      '<IfModule mod_rewrite.c>',
      'RewriteEngine On',
      'RewriteCond %{QUERY_STRING} ^id=12$',
      'RewriteRule ^sale/?$ /offers/12? [R=301,L]',
      'RewriteRule ^old-blog/?$ /blog? [R=301,L]',
      'RewriteRule ^legacy/?$ - [G,L]',
      'RewriteRule ^shop/([^/]+)/(.*)$ /store/$1/items/$2? [R=301,L]',
      'RewriteRule ^product/(\\d+)$ /p/$1? [R=301,L]',
      '</IfModule>',
    ].join('\n'),
  );
});

test('Apache keeps non-Latin paths readable and escapes regex characters', () => {
  const text = generate(run(['/خدمات/a.b,/x']), 'apache').text;
  assert.match(text, /RewriteRule \^خدمات\/a\\\.b\/\?\$ \/x\? \[R=301,L\]/);
});

test('Apache adds NE when the target contains percent escapes', () => {
  const text = generate(run(['/a,/%D8%AE']), 'apache').text;
  assert.match(text, /\[R=301,L,NE\]/);
});

test('Apache skips regex rules that are not anchored at the root', () => {
  const output = generate(run(['~/product/(\\d+),/p/$1']), 'apache');
  assert.deepEqual(output.notes, [
    { code: 'RULE_SKIPPED', line: 1, params: { reason: 'REGEX_NOT_ANCHORED' } },
  ]);
});

test('Nginx output', () => {
  assert.equal(
    generate(report, 'nginx').text,
    [
      '# Generated by redirect-map',
      '# 1) http {} context, for example conf.d/redirects.conf',
      'map $uri $rm_path {',
      '    default "";',
      '    "/old-blog" "301 /blog";',
      '    "/old-blog/" "301 /blog";',
      '    "/legacy" "410";',
      '    "/legacy/" "410";',
      '}',
      'map $request_uri $rm_query {',
      '    default "";',
      '    "/sale?id=12" "301 /offers/12";',
      '    "/sale/?id=12" "301 /offers/12";',
      '}',
      '',
      '# 2) server {} context, then: nginx -t && nginx -s reload',
      'if ($rm_query ~ "^(?<rmcode>\\d{3}) ?(?<rmto>.*)$") { return $rmcode $rmto; }',
      'if ($rm_path ~ "^(?<rmcode>\\d{3}) ?(?<rmto>.*)$") { return $rmcode $rmto; }',
      'rewrite "^/shop/([^/]+)/(.*)$" /store/$1/items/$2? permanent;',
      'rewrite "^/product/(\\d+)$" /p/$1? permanent;',
    ].join('\n'),
  );
});

test('Nginx uses location blocks for status codes rewrite cannot send', () => {
  const text = generate(run(['/a/*,/b/$1,308', '/c/*,410']), 'nginx').text;
  assert.match(text, /location ~ "\^\/a\/\(\.\*\)\$" \{ return 308 \/b\/\$1; \}/);
  assert.match(text, /location ~ "\^\/c\/\(\.\*\)\$" \{ return 410; \}/);
});

test('Nginx skips rows it cannot quote safely', () => {
  const output = generate(run(['/a,"/b;c"']), 'nginx');
  assert.equal(output.notes[0].params.reason, 'UNSAFE_CHARACTERS');
});

test('Nginx rejects patterns with more than nine groups', () => {
  const stars = '/*'.repeat(10);
  const output = generate(run([`${stars},/x`]), 'nginx');
  assert.equal(output.notes[0].params.reason, 'TOO_MANY_GROUPS');
});

test('Netlify and Cloudflare Pages share the _redirects syntax', () => {
  const expected = [
    '# Generated by redirect-map',
    '/old-blog  /blog  301',
    '/shop/:cat/*  /store/:cat/items/:splat  301',
  ].join('\n');
  assert.equal(generate(report, 'netlify').text, expected);
  assert.equal(generate(report, 'cloudflare').text, expected);
});

test('_redirects notes what it cannot express', () => {
  const reasons = generate(report, 'netlify').notes.map((note) => note.params.reason);
  assert.deepEqual(reasons, ['QUERY_NOT_SUPPORTED', 'GONE_NOT_SUPPORTED', 'REGEX_NOT_SUPPORTED']);
});

test('Cloudflare Pages reports the platform limits', () => {
  const rows = Array.from({ length: 2001 }, (_, i) => `/a${i},/b${i}`);
  const notes = generate(run(rows), 'cloudflare').notes;
  assert.deepEqual(notes[0], {
    code: 'LIMIT_EXCEEDED',
    line: null,
    params: { kind: 'static', limit: 2000, count: 2001 },
  });
});

test('_redirects only accepts one trailing wildcard', () => {
  const output = generate(run(['/a/*/b/*,/x/$1']), 'netlify');
  assert.equal(output.notes[0].params.reason, 'WILDCARD_POSITION');
});

test('Vercel output is valid JSON with explicit status codes', () => {
  const { redirects } = JSON.parse(generate(report, 'vercel').text);
  assert.deepEqual(redirects, [
    { source: '/old-blog', destination: '/blog', statusCode: 301 },
    {
      source: '/sale',
      destination: '/offers/12',
      statusCode: 301,
      has: [{ type: 'query', key: 'id', value: '12' }],
    },
    { source: '/shop/:cat/:path*', destination: '/store/:cat/items/:path*', statusCode: 301 },
  ]);
});

test('Vercel escapes characters path-to-regexp treats as syntax', () => {
  const { redirects } = JSON.parse(generate(run(['/a(b),/c']), 'vercel').text);
  assert.equal(redirects[0].source, '/a\\(b\\)');
});

test('CSV neutralises spreadsheet formulas and quotes separators', () => {
  const text = generate(run(['/a,https://x.org/?q=1,2']), 'csv').text;
  assert.ok(text.includes('"https://x.org/?q=1,2"') || text.includes('https://x.org'));
  const unsafe = generate(run(['/a,https://x.org/=cmd']), 'csv').text;
  assert.ok(
    !unsafe.split('\r\n').some((row) => row.split(',').some((cell) => cell.startsWith('='))),
  );
});

test('JSON output lists every rule with its kind', () => {
  const entries = JSON.parse(generate(report, 'json').text);
  assert.deepEqual(
    entries.map((entry) => entry.type),
    ['exact', 'exact', 'exact', 'wildcard', 'regex'],
  );
});

test('an empty map produces an empty but valid file for every format', () => {
  const empty = run([]);
  for (const format of Object.keys(FORMATS)) {
    const file = generate(empty, format);
    assert.equal(typeof file.text, 'string', format);
  }
});

test('an unknown format throws a descriptive error', () => {
  assert.throws(() => generate(report, 'caddy'), /Unknown format "caddy"/);
});
